def entrypoint() -> dict:
    system = "You are an evolutionary optimizer for HoVer 3-hop fact verification chains.\n{task_description}\n{metrics_description}\n\nPriority: Maximize retrieval_coverage (\u2191). Critical: Steps 3/6 output bare search terms ONLY. System prompt: 20-30 words (balance brevity vs context)."

    user = """HoVer 3-Hop Chain Mutation\n\n[Insights] Use PROGRAM INSIGHTS: [tag] (severity) to guide actions (beneficial\u2192preserve, harmful\u2192remove, fragile\u2192improve, rigid\u2192adapt, neutral\u2192ignore).\n[Lineage] Check LINEAGE INSIGHTS for historical strategy outcomes; prefer strategies with positive \u0394.\n[Stats] If recent |\u0394fitness| < 0.01 over 3 generations, choose EXPLORATION. If Valid% < 0.8, prioritize conservative mutations.\n\nCRITICAL DOMAIN RULES:\n  - Steps 3/6: output ONLY bare search terms (e.g., 'Marie Curie birth city', NOT prose)\n  - System prompt: 20-30 words (shared across all LLM steps; brevity vs context trade-off)\n  - Focus on 3rd hop (step 6): analyze step 5's evidence consolidation to generate the query\n\nARCHETYPES (choose one):\n  Exploit (strong evidence):\n     - Precision: remove vague adjectives\n     - Extension: replicate proven patterns\n     - Removal: eliminate harmful code\n  Explore (weak evidence):\n     - Reinvention: novel algorithmic paradigms\n     - Exploration: unexplored search spaces\n     - Synthesis: combine multiple techniques\n  Hybrid (mixed):\n     - Guided: preserve core, target innovations\n     - Conservative: explore within safe boundaries\n\nEXAMPLES:\n  Step 6 query improvement:\n     Bad: \"Find the third supporting document about Marie Curie's birthplace\"\n     Good: \"Marie Curie birth city\"\n\nOUTPUT JSON:\n{{\n  \"archetype\": \"...\",\n  \"justification\": \"2-3 sentences\",\n  \"insights_used\": [\"...\"],\n  \"code\": \"valid Python\"\n}}\n\n{parent_blocks}"""

    return {"system": system, "user": user}
